WITH lines AS (SELECT id, log_ts, latency_ms, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) li AS attr_key, attr_value) SELECT id, status_code, attr_key, CUME_DIST() OVER (ORDER BY status_code DESC) status_code_cume_dist, FIRST_VALUE(latency_ms, TRUE) OVER (PARTITION BY attr_key ORDER BY latency_ms, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_latency_ms, DENSE_RANK() OVER w_hist latency_ms_dense_rank FROM lines WINDOW w_hist AS (ORDER BY latency_ms DESC)
